(7540877, 1207130, 39679, '<td valign="top">I like this shot but I''m not sure why you chose to make it sepia.</td>', 'I like this shot but I''m not sure why you chose to make it sepia.', '2017-10-25 12:31:07.000000', NULL, 1),
(7540879, 1206999, 39679, '<td valign="top">Great use of bokeh!</td>', 'Great use of bokeh!', '2017-10-25 12:31:44.000000', NULL, 1),
(7540881, 1207017, 39679, '<td valign="top">The color and clarity in this shot are awesome but there is so much clutter and nothing to lead the eye to the subject.  Shots like this are often best if you zoom way in.  Tell a story of one ball carrier against two defense men.</td>', 'The color and clarity in this shot are awesome but there is so much clutter and nothing to lead the eye to the subject.  Shots like this are often best if you zoom way in.  Tell a story of one ball carrier against two defense men.', '2017-10-25 12:34:53.000000', NULL, 1),
(7540882, 1207152, 39679, '<td valign="top">Awesome to use background blur to give a sense of motion!</td>', 'Awesome to use background blur to give a sense of motion!', '2017-10-25 12:36:19.000000', NULL, 1),
